module menu_screens (
    input  wire        clk,
    input  wire        reset,
    input  wire        frame_tick,
    input  wire [9:0]  pixel_x,
    input  wire [9:0]  pixel_y,
    input  wire        show_screen,
    input  wire [2:0]  screen_page,
    input  wire [1:0]  highlight,
    input  wire [13:0] best_score,
    input  wire [13:0] last_score,
    input  wire        show_banner,
    input  wire [2:0]  banner_type,
    input  wire [5:0]  banner_hp,
    input  wire [5:0]  banner_max_hp,
    output wire        banner_active,
    output wire [11:0] banner_rgb,
    output reg         active,
    output reg  [11:0] rgb
);
    localparam [2:0] MENU = 3'd0, CHOOSE_PLANT = 3'd1, SCORES = 3'd2, IDLE = 3'd3,
                     CHOOSE_MEAT = 3'd4, VICTORY = 3'd5, DEFEAT = 3'd6;
    reg [2:0] page;
    reg [1:0] focus;
    always @(posedge clk) begin
        if (reset) begin
            active <= 1'b1;
            page <= MENU;
            focus <= 2'd0;
        end else if (frame_tick) begin
            active <= show_screen;
            page <= screen_page;
            focus <= highlight;
        end
    end

    // The two 16:9 selection paintings retain their original proportions.
    // The menu and result artwork fill the entire 640x480 frame.
    wire letterbox = page == CHOOSE_PLANT || page == CHOOSE_MEAT;
    wire end_of_line = pixel_x >= 10'd798;
    wire [9:0] fetch_x = end_of_line ? (pixel_x - 10'd798) : (pixel_x + 10'd2);
    wire [9:0] fetch_y = !end_of_line ? pixel_y :
                         (pixel_y == 10'd524) ? 10'd0 : pixel_y + 10'd1;
    wire [9:0] page_y = letterbox ? fetch_y - 10'd60 : fetch_y;
    wire [10:0] doubled_x = {fetch_x, 1'b0};
    wire [10:0] doubled_y = {page_y, 1'b0};
    wire [7:0] screen_col = doubled_x / 11'd5;
    wire [7:0] screen_row = doubled_y / 11'd5;
    wire [2:0] art_page = (page == CHOOSE_PLANT) ? 3'd1 : (page == CHOOSE_MEAT) ? 3'd2 :
                          (page == VICTORY) ? 3'd3 : (page == DEFEAT) ? 3'd4 : 3'd0;
    wire [17:0] page_offset = (art_page == 3'd1) ? 18'd49152 :
                              (art_page == 3'd2) ? 18'd86016 :
                              (art_page == 3'd3) ? 18'd122880 :
                              (art_page == 3'd4) ? 18'd172032 : 18'd0;
    wire fetch_valid = active && (fetch_x < 10'd640) && (fetch_y < 10'd480) &&
                       (!letterbox || (fetch_y >= 10'd60 && fetch_y < 10'd420));
    wire fetch_banner = !active && show_banner && fetch_x >= 10'd192 && fetch_x < 10'd448 &&
                        fetch_y >= 10'd4 && fetch_y < 10'd132;
    wire [7:0] banner_fetch_dx = fetch_x - 10'd192;
    wire [6:0] banner_fetch_dy = fetch_y - 10'd4;
    wire [17:0] address = fetch_banner ?
         18'd221184 + {3'd0, banner_type, 12'd0} + {6'd0, banner_fetch_dy[6:1], banner_fetch_dx[7:2]} :
         fetch_valid ? page_offset + {2'd0, screen_row, screen_col} : 18'd0;

    wire [7:0] color_index;
    spore_pixel_rom u_pixels (.clk(clk), .address(address), .pixel(color_index));

    (* rom_style = "block" *) reg [11:0] palette [0:1359];
    initial $readmemh("menu_palette.mem", palette);
    reg [2:0] art_page_d1, banner_type_d1;
    reg valid_d1, valid_d2, plate_d1, plate_d2, high_nibble_d1, opaque_d2;
    reg [11:0] artwork;
    wire [3:0] plate_index = high_nibble_d1 ? color_index[7:4] : color_index[3:0];
    wire [10:0] palette_addr = plate_d1 ? 11'd1280 + {4'd0, banner_type_d1, plate_index} :
                                           {art_page_d1, color_index};
    always @(posedge clk) begin
        art_page_d1 <= art_page;
        valid_d1 <= fetch_valid;
        plate_d1 <= fetch_banner;
        banner_type_d1 <= banner_type;
        high_nibble_d1 <= banner_fetch_dx[1];
        artwork <= palette[palette_addr];
        valid_d2 <= valid_d1;
        plate_d2 <= plate_d1;
        opaque_d2 <= (plate_index != 4'd0);
    end

    // Fill the pre-drawn slot in proportion to the selected enemy's own maximum HP.
    wire [7:0] banner_dx = pixel_x - 10'd192;
    wire [6:0] banner_dy = pixel_y - 10'd4;
    wire [6:0] slot_x = banner_dx[7:1];
    wire [5:0] slot_y = banner_dy[6:1];
    wire [5:0] slot_top = (banner_type == 3'd0) ? 6'd45 : (banner_type == 3'd1) ? 6'd47 :
                          (banner_type == 3'd2) ? 6'd43 : 6'd41;
    wire [5:0] slot_bottom = (banner_type == 3'd0) ? 6'd49 : (banner_type == 3'd1) ? 6'd52 :
                             (banner_type == 3'd2) ? 6'd48 : 6'd47;
    wire [6:0] slot_position = slot_x - 7'd50;
    wire [11:0] bar_position = slot_position * banner_max_hp;
    wire [11:0] bar_health = 12'd63 * banner_hp;
    wire bar_pixel = slot_x >= 7'd50 && slot_x < 7'd113 && slot_y >= slot_top && slot_y < slot_bottom &&
                     (banner_max_hp != 6'd0) && bar_position < bar_health;
    assign banner_active = plate_d2 && (opaque_d2 || bar_pixel);
    assign banner_rgb = bar_pixel ? ((slot_y == slot_top) ? 12'hF78 : 12'hD34) : artwork;

    function corner_border;
        input [9:0] x, y, x0, y0, x1, y1;
        reg [9:0] left, right, top, bottom;
        begin
            left = x - x0;
            right = x1 - x;
            top = y - y0;
            bottom = y1 - y;
            corner_border = (x >= x0 && x <= x1 && y >= y0 && y <= y1) &&
                (((left < 5 || right < 5) && (top < 23 || bottom < 23)) ||
                 ((top < 5 || bottom < 5) && (left < 23 || right < 23)));
        end
    endfunction

    reg focus_ink;
    always @(*) begin
        focus_ink = 1'b0;
        case ({page, focus})
            {MENU, 2'd0}: focus_ink = corner_border(pixel_x, pixel_y, 10'd199, 10'd302, 10'd440, 10'd373);
            {MENU, 2'd1}: focus_ink = corner_border(pixel_x, pixel_y, 10'd207, 10'd376, 10'd315, 10'd442);
            {MENU, 2'd2}: focus_ink = corner_border(pixel_x, pixel_y, 10'd322, 10'd376, 10'd430, 10'd442);
            default: ;
        endcase
    end

    function [19:0] as_decimal;
        input [13:0] value;
        integer bit_index, digit;
        reg [19:0] bcd;
        begin
            bcd = 20'd0;
            for (bit_index = 13; bit_index >= 0; bit_index = bit_index - 1) begin
                for (digit = 0; digit < 5; digit = digit + 1)
                    if (bcd[digit*4 +: 4] >= 4'd5) bcd[digit*4 +: 4] = bcd[digit*4 +: 4] + 4'd3;
                bcd = {bcd[18:0], value[bit_index]};
            end
            as_decimal = bcd;
        end
    endfunction

    function [34:0] glyph;
        input [7:0] character;
        begin
            case (character)
                "0": glyph = 35'b01110_10001_10011_10101_11001_10001_01110;
                "1": glyph = 35'b00100_01100_00100_00100_00100_00100_01110;
                "2": glyph = 35'b01110_10001_00001_00010_00100_01000_11111;
                "3": glyph = 35'b11110_00001_00001_01110_00001_00001_11110;
                "4": glyph = 35'b00010_00110_01010_10010_11111_00010_00010;
                "5": glyph = 35'b11111_10000_10000_11110_00001_00001_11110;
                "6": glyph = 35'b01110_10000_10000_11110_10001_10001_01110;
                "7": glyph = 35'b11111_00001_00010_00100_01000_01000_01000;
                "8": glyph = 35'b01110_10001_10001_01110_10001_10001_01110;
                "9": glyph = 35'b01110_10001_10001_01111_00001_00001_01110;
                default: glyph = 35'd0;
            endcase
        end
    endfunction

    localparam [419:0] TITLE_MASK = 420'h3d144e3df44e78f44945144125105044545144115105044f7d13cf3d104e4514514414510414514514414510413cf38e3df3ce79e;
    localparam [419:0] BEST_MASK = 420'h7d139e3c010f7cf0494414001100510454414001100513cf44138010e3cf0514410401010510514410401010517cf39e7807de7cf;
    localparam [419:0] LAST_MASK = 420'h7d139e3c010f45f0494414001104410454414001104413cf44138010e7c10514410401014410514410401014417cf39e7807de381;
    localparam [419:0] BACK_MASK = 420'h00000045e44f0110000002414510110000001414510110000000c17cf01f00000014145101100000024145101100000045e38f00e;
    localparam [419:0] IDLE_PROMPT_MASK = 420'h00001100f3df44100001101040124100001101040114100001f00e38f3cf00001100104145100001100104145100000e01e79f3cf;

    function label_pixel;
        input [419:0] mask;
        input [9:0] x, y, x0, y0;
        reg [7:0] dx, dy;
        reg [5:0] col;
        reg [2:0] line;
        reg [8:0] pixel_index;
        begin
            dx = x - x0;
            dy = y - y0;
            col = dx[7:2];
            line = dy[4:2];
            pixel_index = {line, 6'd0} - {4'd0, line, 2'd0} + {3'd0, col};
            label_pixel = (x >= x0 && x < x0 + 10'd240 && y >= y0 && y < y0 + 10'd28) &&
                          mask[pixel_index];
        end
    endfunction

    reg [19:0] best_dec, last_dec;
    always @(posedge clk) begin
        best_dec <= as_decimal(best_score);
        last_dec <= as_decimal(last_score);
    end

    wire frame_area = pixel_x < 640 && pixel_y < 480;
    wire board_area = pixel_x >= 112 && pixel_x < 528 && pixel_y >= 104 && pixel_y < 380;
    wire board_inner = pixel_x >= 118 && pixel_x < 522 && pixel_y >= 110 && pixel_y < 374;
    wire score_row_best = pixel_y >= 10'd203 && pixel_y < 10'd231;
    wire score_row_last = pixel_y >= 10'd251 && pixel_y < 10'd279;
    wire [19:0] selected_score = score_row_best ? best_dec : last_dec;
    wire [7:0] score_dx = pixel_x - 10'd386;
    wire [4:0] score_dy = score_row_best ? pixel_y - 10'd203 : pixel_y - 10'd251;
    wire [2:0] score_slot = (score_dx < 8'd24) ? 3'd0 :
                            (score_dx < 8'd48) ? 3'd1 :
                            (score_dx < 8'd72) ? 3'd2 :
                            (score_dx < 8'd96) ? 3'd3 : 3'd4;
    wire [7:0] slot_start = {score_slot, 4'd0} + {score_slot, 3'd0};
    wire [4:0] digit_dx = score_dx - slot_start;
    wire [2:0] digit_x = digit_dx[4:2];
    wire [2:0] digit_y = score_dy[4:2];
    wire [2:0] score_digit = 3'd4 - score_slot;
    wire [3:0] digit = selected_score[{score_digit, 2'd0} +: 4];
    wire [34:0] digit_mask = glyph(8'h30 + {4'd0, digit});
    wire [5:0] digit_bit = 6'd34 - ({1'b0, digit_y, 2'd0} + {3'd0, digit_y}) - {3'd0, digit_x};
    wire score_ink = (score_row_best || score_row_last) && (pixel_x >= 10'd386) &&
                     (pixel_x < 10'd506) && (digit_x < 3'd5) && digit_mask[digit_bit];
    wire board_text = label_pixel(TITLE_MASK, pixel_x, pixel_y, 10'd202, 10'd132) ||
                      label_pixel(BEST_MASK, pixel_x, pixel_y, 10'd134, 10'd203) ||
                      label_pixel(LAST_MASK, pixel_x, pixel_y, 10'd134, 10'd251) ||
                      label_pixel(BACK_MASK, pixel_x, pixel_y, 10'd250, 10'd326) || score_ink;
    wire idle_text = label_pixel(IDLE_PROMPT_MASK, pixel_x, pixel_y, 10'd238, 10'd336);
    wire [11:0] dim_art = {1'b0, artwork[11:9], 1'b0, artwork[7:5], 1'b0, artwork[3:1]};

    always @(*) begin
        rgb = (active && frame_area && letterbox) ? 12'h211 : 12'h000;
        if (valid_d2 && frame_area) begin
            case (page)
                SCORES: rgb = board_text ? 12'hFED : board_inner ? 12'h532 : board_area ? 12'hDB7 : dim_art;
                IDLE: rgb = idle_text ? 12'hFED :
                            (pixel_y >= 300) ? 12'h321 : dim_art;
                default: rgb = focus_ink ? 12'hFF8 : artwork;
            endcase
        end
    end
endmodule

// Generated pixel ROM for Artix-7. Each bank stores 4096 bytes.
module spore_pixel_rom(input wire clk, input wire [17:0] address, output wire [7:0] pixel);
`ifdef SYNTHESIS
    reg [5:0] bank_d1;
    wire [7:0] block_data [0:58];
    always @(posedge clk) bank_d1 <= address[17:12];
    assign pixel = (bank_d1 < 6'd59) ? block_data[bank_d1] : 8'd0;
    wire [31:0] data_0;
    RAMB36E1 #(
        .RAM_MODE("TDP"), .READ_WIDTH_A(9), .WRITE_WIDTH_A(9),
        .READ_WIDTH_B(0), .WRITE_WIDTH_B(0), .DOA_REG(0), .DOB_REG(0),
        .INIT_00(256'h7a101710823d1017484848484848185d185d5d5d1f3c3c3c3c1f3c1f481f1f1f),
        .INIT_01(256'hc3c3c3c34d2a2a2a4d4dee2a2a8e2a2a2a5b8e2a2e2e2e2e2e2eeee73d3d823d),
        .INIT_02(256'h4d4d4d4d4d4d4dee4d21c3c3c3c3c3c3ee2a2a2a2a2a2a2a2a2a2a2a2a4dc3c3),
        .INIT_03(256'h9b2e4d4d4d4d4d4d2ec3c3c32e4d4d4d4d4d4d4d4dee2ec3c3c3c3c3c3c34dee),
        .INIT_04(256'hee2e2ec32121219b4d4d4d4d4d4d4d4d4d1b9bc39b9b9b4d4d4d4d4d9b9b9b9b),
        .INIT_05(256'hc32eeeeeeeeeee4d4d4d4d4d4d4d4d9bc3c3c3c3c3c3c34d4d4d4d4d4deeee2a),
        .INIT_06(256'h5e5e3de7ea2e2e2e2e2e2e2e2a2a2a2a2a2a2a4d4d4deeeeee2a4dc3c3c3c3c3),
        .INIT_07(256'h3c3c1f1f1f485d3c3c3c3c3c1f5d18103d3d1017173d3d10103d3d82e7aa4848),
        .INIT_08(256'h103d823d3d88101748171717170d185d1848181f1f1f1f5d181f5d48485d181f),
        .INIT_09(256'h9ac3c39ac3eeee4d2a2a8e8e8e8e8e8e8e2a5b5beec32c2c4d4d4d2a823d3d3d),
        .INIT_0A(256'h4d4d2e2e2e2e2e2e2e215a5ac3c3c39a9beeeeeeeeeeeeeeeeeeeeeeee4dc39a),
        .INIT_0B(256'h2e2e2e4d4d2e2e2e9b5a5a5ac34d4d4d2e2e2e2e4d4d2ec321215a5a5a5ac34d),
        .INIT_0C(256'h2ec3c3c321215a9b4d4d4d4d4d4d4d4d4d4dc3c3c3c3c32e2e2e2e2e9b9b9b2e),
        .INIT_0D(256'h9a2e4d4d4d4d4d4d2e2e2e2e2e2e2ec39ac3c3c3c39ac34d4d4d4d2e2e4d4d4d),
        .INIT_0E(256'h88103de7ee4d4d2e2c2e2c4d2a2a5b2a2a2a2a4d4d4d4d4d4d4dc39a9a9ac3c3),
        .INIT_0F(256'h1f1f1f5d18480d1818185d1f1f1f18481017103d3d3d82823d3d103de7e7823d),
        .INIT_10(256'h17aa48181f1f1f1f5d184848185d5d1f3c1f1f3c573c5d18481848481f1f1f3c),
        .INIT_11(256'h2e2e2e2e4deaafaf3d66666666663d663d3d3de7e7ea2eee2a8e8e2ae74848aa),
        .INIT_12(256'h2aea8e8eeaeaeaea8e05c3c3c3c3c3c3c34d2a2a2a2aea8e8e8e8e8ed08eea4d),
        .INIT_13(256'h4d2aea8eeaeaeaea1b2e2e2e2eea8e8eeaeaeaeaea2a2a4dc3c39bc3c3c3c34d),
        .INIT_14(256'h9bc39b9b9b9b9b2a2a2aea2aea8e8e8e8eea4d4d4d4d4d2a1beaea1b4d4d4d4d),
        .INIT_15(256'h4d8e8e8e8e8eea8e8e8eeaeaeaea2e9b9bc3c3c3c3c33beaeaeaea8eeaea2a2a),
        .INIT_16(256'h3d1717d02a8e8e2a2a2eeae783e782838e8e8e8ee7e7afafd0ea4d4d2e9bc3c3),
        .INIT_17(256'h1f3c3c3c1f5d1818185d181f1f1f1f1f1f1f18181848481717171717173d3d3d),
        .INIT_18(256'h181f1f1f1f1f5d485d18485d1f1f1f3c3c3c1f1f1f18aa485d18481f3c571f3c),
        .INIT_19(256'hee2aee2a8e8e3d10666666663d3d3d3d3d10103d3d3d8e5b8e8e83e7833d4818),
        .INIT_1A(256'h8ed0afafafafafafafaf052e2e9b9b9b2e4d8e8e8e8ed0a43d3d3d3d3d3d3d8e),
        .INIT_1B(256'h2e4deaea1b2a2a2a2a2aeeeeee2a8e8e8e8e8eea2a2a2a2a9b9b2e2e2e2e2e2a),
        .INIT_1C(256'h2e2e9b9b9bc34d2a2a2a2a2a2a8e8e8e8eeaee2a2a2a8e8e8e8e8e8e4d4d4d4d),
        .INIT_1D(256'h8ee750a4a4a4e78eafafafafaf8e4dee4d2e2e2e9b05d0d0d0d0d0d0d0d08e3b),
        .INIT_1E(256'h1717d02a2a2a2a8e8e8ee78282e7e782823d3d3d3d3d3d3da4ea2a2a2a4d2e2e),
        .INIT_1F(256'h1f3c3c3c3c1f1f5d181f1f185d5d18481f1f1f1f1f1f5d1f1818184848171717),
        .INIT_20(256'h1f1f1f1818185d5d5d1f1f3c3c3c3c3c5d181f1f1748185d3c1f1f1f3c571f3c),
        .INIT_21(256'heaeaea8e8eea8e666666663d3d3d3d3d6610663d105e10e7838383e7e7e7171f),
        .INIT_22(256'hd0afafafafafafafd0afd04d4dee4d4d2a2ad03da4505050a4a4a4a43da4e7af),
        .INIT_23(256'h9b2e4d1b2a2a2a2a2a2a4deeee4d2a2a2a2a2a2a2aea8e8e054deeee2aee2a2a),
        .INIT_24(256'heeee4d2e2e2e8e8e8e2a2a2aea2a2a2a2a4d4d4d4d4dea8e8e2a2a4d9b9b9b2e),
        .INIT_25(256'ha4afafafafafd08e8e8e8eafd02aeeeeeeee2aee2ad0d0d0d0d0d0d0d0d0d02a),
        .INIT_26(256'h48e78e8e8eea2aeae7103d3d3d3d3d3d3d1010663d3d3d3d8e2a2a2a2a2a2ad0),
        .INIT_27(256'h481f1f3c3c3c3c1f1f1f1f1f1f1f5d18181f1f1f1f1f1f1f1f1f1f1f1f1f1848),
        .INIT_28(256'h5d1f1818181f1f1f1f1f1f3c3c3c3c5d48183c1f181f3c3c3c3c1f1f1f3c1f3c),
        .INIT_29(256'hafea8e8e8e8e2ae766666666661010105e5e5e5e5eaa483d8e8e8e8ee7e7e748),
        .INIT_2A(256'heaafafafafaf8eafafaf50eaee2a2a2a2aee2aa4a450a4a4e7e7a43d3d3d3d66),
        .INIT_2B(256'h2e4d2a2a2a2a2a2a2aea2a2a2a2a2a2aea2a2aea8ed0d0afd02a2a2a2a2a2aee),
        .INIT_2C(256'heeee2aee4deaafd0d08e8e8e8e8eeaea2a4d4d4d4dee2a2a2a2a2a4d2e2e4d2e),
        .INIT_2D(256'h3de7a4a4afafaf8eafaf8e8eeaeeeeeeeeeeeeeeead0d0d0afd0d0d0d0d08eee),
        .INIT_2E(256'h108e8e8e8e8e8e8e665e5e5e5e10101010106666666666af2a2a2a2a2a2a8e3d),
        .INIT_2F(256'h4818181f3c3c3c3c3c1f1f1f1f1f1f1f1f1f18181f1f1f181f48181f1f1f1f1f),
        .INIT_30(256'h185d181f1f1f1f1f1f1f1f1f3c3c3c5d181f3c1f1f1f1f3c3c3c1f1f1f1f1f1f),
        .INIT_31(256'h3d8e8e8e8e8e8e8e3d666610103d105e5e5e5e5e5e5e1717832a8e8e8ee7e7e7),
        .INIT_32(256'h2a8eafafafafafaf505050afee2a2a2a2a2aee8e3da4e7e7e7e73d6666666666),
        .INIT_33(256'hee2a2aeaea8e8e8ed0af8e2a2a2aead0afd0eaead0d0afafaf8e2a2a2a2a2a2a),
        .INIT_34(256'heeeeeeee2ad0afafafafafafafafafafeaeeee4d4d2a2a2a2a2a2a2a4deeeeee),
        .INIT_35(256'h3d3d3d3da4e7e7a4a4a4a4d0eeeeeeeeeeeeeeee8e8e8eea8ed0d0d0d0d02aee),
